import React, { useEffect, useMemo, useState } from 'react';
import { getCart, updateQty, removeItem, clearCart, totalAmount } from '../lib/cart';
import api from '../lib/api';
import { MIDTRANS_CLIENT_KEY } from '../config';

function loadMidtrans(clientKey){
  return new Promise((resolve, reject) => {
    if (document.getElementById('midtrans-script')) return resolve();
    const s = document.createElement('script');
    s.id = 'midtrans-script';
    s.src = `https://app.sandbox.midtrans.com/snap/snap.js`;
    s.setAttribute('data-client-key', clientKey);
    s.onload = () => resolve();
    s.onerror = reject;
    document.body.appendChild(s);
  });
}

export default function Cart(){
  const [items, setItems] = useState([]);

  useEffect(()=>{
    setItems(getCart());
    const onUpd = ()=> setItems(getCart());
    window.addEventListener('cart_updated', onUpd);
    return ()=> window.removeEventListener('cart_updated', onUpd);
  },[]);

  function inc(id){ setItems(updateQty(id, (items.find(i=>i.product_id===id)?.quantity||0) + 1)); }
  function dec(id){ setItems(updateQty(id, (items.find(i=>i.product_id===id)?.quantity||0) - 1)); }
  function del(id){ setItems(removeItem(id)); }
  function clearAll(){ setItems(clearCart()); }

  const total = useMemo(()=> totalAmount(), [items]);

  async function checkout(){
    if (!items.length) return alert('Keranjang kosong');
    const token = localStorage.getItem('hr_token');
    if (!token) {
      if (window.confirm('Anda harus login terlebih dahulu. Login sekarang?')) window.location.href = '/login';
      return;
    }
    try{
      await loadMidtrans(MIDTRANS_CLIENT_KEY);
      const resp = await api.post('/checkout', { items });
      const token_snap = resp.data.snap_token;
      const orderId = resp.data?.order?.order_number;
      if (!token_snap) return alert('Gagal membuat transaksi');
      window.snap.pay(token_snap, {
        onSuccess: function(){
          alert('Pembayaran sukses');
          clearAll();
          if (orderId) api.post('/midtrans/refresh', { order_id: orderId }).catch(()=>{});
        },
        onPending: function(){
          alert('Pembayaran pending');
          if (orderId) api.post('/midtrans/refresh', { order_id: orderId }).catch(()=>{});
        },
        onError: function(){
          alert('Pembayaran error');
        }
      });
    }catch(err){
      const data = err.response?.data;
      let msg = 'Checkout gagal';
      if (data) msg = data.message || data.details || data.error || msg;
      alert(msg);
      console.error('Checkout error', err);
    }
  }

  return (
    <div style={{padding:20, fontFamily:'sans-serif'}}>
      <header style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>
        <strong>Keranjang</strong>
        <nav>
          <a href="/">Home</a>
        </nav>
      </header>

      {items.length===0 ? (
        <div>Keranjang kosong. <a href="/">Belanja sekarang</a></div>
      ) : (
        <div>
          <table border="1" cellPadding={8} style={{width:'100%'}}>
            <thead>
              <tr>
                <th>Produk</th>
                <th>Harga</th>
                <th style={{width:180}}>Qty</th>
                <th>Subtotal</th>
                <th>Aksi</th>
              </tr>
            </thead>
            <tbody>
              {items.map(it => (
                <tr key={it.product_id}>
                  <td>{it.name}</td>
                  <td>{it.price}</td>
                  <td>
                    <button onClick={()=>dec(it.product_id)}>-</button>
                    <span style={{display:'inline-block', minWidth:40, textAlign:'center'}}>{it.quantity}</span>
                    <button onClick={()=>inc(it.product_id)}>+</button>
                  </td>
                  <td>{(it.price||0)*(it.quantity||0)}</td>
                  <td><button onClick={()=>del(it.product_id)}>Hapus</button></td>
                </tr>
              ))}
            </tbody>
          </table>

          <div style={{marginTop:12, display:'flex', justifyContent:'space-between', alignItems:'center'}}>
            <div>
              <button onClick={clearAll}>Kosongkan Keranjang</button>
            </div>
            <div style={{textAlign:'right'}}>
              <div><strong>Total:</strong> {total}</div>
              <div style={{marginTop:8}}>
                <button onClick={checkout} style={{padding:'8px 16px'}}>Checkout</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
